import java.security.SecureRandom
import java.nio.charset.StandardCharsets
import java.util.Base64
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import java.net.{ServerSocket, Socket}
import java.io.{BufferedReader, InputStreamReader, PrintWriter}
import java.util.concurrent.ConcurrentHashMap

object TokenAuth {
  private val SECRET_KEY = sys.env.getOrElse("HMAC_SECRET", 
    throw new RuntimeException("HMAC_SECRET environment variable required"))
  private val sessions = new ConcurrentHashMap[String, SessionData]()
  private val secureRandom = new SecureRandom()

  case class SessionData(userId: String, createdAt: Long, permissions: Set[String])

  // Generate a cryptographically secure session token
  def generateSessionToken(userId: String): String = {
    val tokenBytes = new Array[Byte](32)
    secureRandom.nextBytes(tokenBytes)
    val token = Base64.getUrlEncoder.withoutPadding().encodeToString(tokenBytes)
    val session = SessionData(userId, System.currentTimeMillis(), Set("read", "write"))
    sessions.put(token, session)
    token
  }

  // Create HMAC signature for integrity verification
  def createSignature(data: String): String = {
    val mac = Mac.getInstance("HmacSHA256")
    val keySpec = new SecretKeySpec(
      SECRET_KEY.getBytes(StandardCharsets.UTF_8), "HmacSHA256")
    mac.init(keySpec)
    val signature = mac.doFinal(data.getBytes(StandardCharsets.UTF_8))
    Base64.getUrlEncoder.withoutPadding().encodeToString(signature)
  }

  // Timing-safe comparison to prevent timing attacks
  // Compares two token strings in constant time
  def constantTimeEquals(a: String, b: String): Boolean = {
    if (a == null || b == null) return false
    val aBytes = a.getBytes(StandardCharsets.UTF_8)
    val bBytes = b.getBytes(StandardCharsets.UTF_8)
    // Short-circuit on length mismatch would leak length info,
    // so we compare against the longer length, padding conceptually
    if (aBytes.length == 0 && bBytes.length == 0) return true
    if (aBytes.length == 0 || bBytes.length == 0) return false
    var result = aBytes.length ^ bBytes.length
    val maxLen = Math.max(aBytes.length, bBytes.length)
    var i = 0
    while (i < maxLen) {
      val aByte = if (i < aBytes.length) aBytes(i) else 0
      val bByte = if (i < bBytes.length) bBytes(i) else 0
      result |= (aByte ^ bByte)
      i += 1
    }
    result == 0
  }

  // Validate a signed request
  def validateRequest(token: String, payload: String, providedSig: String): Option[SessionData] = {
    val session = sessions.get(token)
    if (session == null) return None

    val expectedSig = createSignature(s"$token:$payload")
    if (!constantTimeEquals(expectedSig, providedSig)) return None

    // Check session expiry (24 hours)
    val now = System.currentTimeMillis()
    if (now - session.createdAt > 86400000L) {
      sessions.remove(token)
      return None
    }

    Some(session)
  }

  // Simple HTTP-like request handler
  def handleConnection(socket: Socket): Unit = {
    val reader = new BufferedReader(new InputStreamReader(socket.getInputStream))
    val writer = new PrintWriter(socket.getOutputStream, true)

    try {
      val requestLine = reader.readLine()
      if (requestLine == null) return

      val parts = requestLine.split(" ", 4)
      if (parts.length < 4) {
        writer.println("ERROR: Invalid request format")
        return
      }

      val Array(action, token, signature, payload) = parts

      action match {
        case "LOGIN" =>
          // In production, verify credentials against a database
          val userId = payload
          val newToken = generateSessionToken(userId)
          val sig = createSignature(s"$newToken:welcome")
          writer.println(s"OK $newToken $sig")

        case "ACCESS" =>
          validateRequest(token, payload, signature) match {
            case Some(session) =>
              if (session.permissions.contains("read")) {
                writer.println(s"OK: Access granted for ${session.userId}")
              } else {
                writer.println("DENIED: Insufficient permissions")
              }
            case None =>
              writer.println("DENIED: Invalid or expired session")
          }

        case "ADMIN" =>
          validateRequest(token, payload, signature) match {
            case Some(session) =>
              if (session.permissions.contains("admin")) {
                writer.println(s"OK: Admin action performed: $payload")
              } else {
                writer.println("DENIED: Admin access required")
              }
            case None =>
              writer.println("DENIED: Invalid or expired session")
          }

        case _ =>
          writer.println("ERROR: Unknown action")
      }
    } finally {
      socket.close()
    }
  }

  def main(args: Array[String]): Unit = {
    val port = sys.env.getOrElse("PORT", "8443").toInt
    val serverSocket = new ServerSocket(port)
    println(s"Token auth service listening on port $port")

    while (true) {
      val clientSocket = serverSocket.accept()
      new Thread(() => handleConnection(clientSocket)).start()
    }
  }
}
